  const legendAt = k => all.slice(0, k).reduce((a, b) => a + 36 + 7 * b.tag.length, 16);
  const scale = Math.max(1, Math.max(320, hasLegend ? legendAt(all.length) : 0) / wide, 200 / high), W = wide * scale, H = high * scale;
